type Request = {
    method: string;
    path: string;
    token?: string;
    body?: unknown;
};

type Response = {
    status: number;
    body: Record<string, unknown>;
};

const sessions: Record<string, "member" | "admin"> = {
    "member-token": "member",
    "admin-token": "admin",
};

function routeRequest(request: Request): Response {
    const detail = /^\/orders\/(\d+)$/.exec(request.path);
    const isCollection = request.path === "/orders";

    if (!isCollection && detail === null) {
        return { status: 404, body: { error: "not_found" } };
    }

    const role =
        request.token !== undefined &&
        Object.prototype.hasOwnProperty.call(sessions, request.token)
            ? sessions[request.token]
            : undefined;
    if (role === undefined) {
        return { status: 401, body: { error: "authentication_required" } };
    }

    if (isCollection && request.method === "POST") {
        if (role !== "admin") {
            return { status: 403, body: { error: "forbidden" } };
        }
        const body = request.body as { item?: unknown; quantity?: unknown } | undefined;
        if (
            typeof body?.item !== "string" ||
            body.item.length === 0 ||
            !Number.isInteger(body.quantity) ||
            (body.quantity as number) <= 0
        ) {
            return { status: 400, body: { error: "invalid_body" } };
        }
        return { status: 201, body: { item: body.item, quantity: body.quantity } };
    }

    if (isCollection && request.method === "GET") {
        return { status: 200, body: { orders: [1, 2] } };
    }

    if (detail !== null && request.method === "GET") {
        return { status: 200, body: { id: Number(detail[1]) } };
    }

    return { status: 405, body: { error: "method_not_allowed" } };
}
